mapper.select:
SELECT EVENT_TYPE, CALLER_SYSTEM, FILE_NAME, BYTE_SIZE, ENCRYPTED_YN, VIEWER_NAME, TOOK_MS, RESULT_CODE, MESSAGE, CLIENT_IP, INPUT_DATETIME AS CHANGED_AT FROM wo_view_event_log WHERE INPUT_DATETIME >= #{since}
AND EVENT_TYPE = #{eventType}
ORDER BY EVENT_SEQ DESC FETCH FIRST #{limit} ROWS ONLY

SELECT COUNT(*) FROM wo_view_event_log
 WHERE INPUT_DATETIME >= #{since}
   AND EVENT_TYPE = #{eventType}

SELECT AVG(TOOK_MS) FROM wo_view_event_log
 WHERE INPUT_DATETIME >= #{since}
   AND EVENT_TYPE = #{eventType}
   AND TOOK_MS IS NOT NULL
